import {scientificChart} from './labform-plotly.js';
import {createLabStudio3} from './labform-studio3.js';
import {initThemedChart,chartBackground} from './workspace-theme-charts.js';
import {saveConflict} from './save-conflict.js';
import {clone,uid,stamp,templates,createExperiment,evaluateExperiment,statistics,propagate,convertUnit,formatNumber,predicted} from './labform-pro-model.js';
import {parseDelimited,rowsToTable} from './tablemind-pro-model.js';
import {echarts} from './vendor/table-tools.js';
const nav={home:'实验工作台',create:'AI 实验创建',notebook:'电子实验记录本',data:'实验数据',capture:'采集中心',compute:'科学计算',plot:'科学绘图',analysis:'AI 实验分析',report:'实验报告',templates:'模板与管理'};
let workspaceReady;const api=async(path,data,method='POST')=>{workspaceReady||=fetch('/api/workspace/session',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(r=>{if(!r.ok)throw Error('本机工作区会话不可用');});await workspaceReady;const response=await fetch('/api/lab'+path,{method,headers:{'Content-Type':'application/json'},...(method==='GET'?{}:{body:JSON.stringify(data||{})})}),result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error||'实验服务请求失败'),{status:response.status});return result;};
export function createLabForm(ctx){let lastSaveError=false;let state={projects:[],templates:[],audit:[]},area='home',activeId='',ready=false,error='',busy='',candidate=null,guide=null,importDraft=null,computed=null,plotChart=null,residualChart=null,overviewCharts=[],extraResult=null,search='',showArchived=false;const esc=v=>ctx.escape(String(v??'')),rich=v=>esc(v).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/^[-] (.+)$/gm,'• $1').replace(/\n/g,'<br>'),p=()=>state.projects.find(p=>p.id===activeId)||state.projects[0],fmt=v=>formatNumber(v,p()?.precision||6,p()?.notation||'normal'),paint=()=>{overviewCharts.forEach(c=>c.dispose());overviewCharts=[];plotChart?.dispose();residualChart?.dispose();plotChart=residualChart=null;ctx.render();},sync=r=>{if(r.state){state=r.state;activeId=state.projects.some(p=>p.id===activeId)?activeId:state.activeProjectId||state.projects[0]?.id;}},safe=()=>{try{return p()?.rows.length?evaluateExperiment(p()):null;}catch(e){return{error:e.message,stats:{},points:[],rows:[],findings:[]};}},fieldOptions=(value,blank=false)=>`${blank?'<option value="">不使用</option>':''}${(p()?.fields||[]).map(f=>`<option value="${f.id}" ${value===f.id?'selected':''}>${esc(f.label)} (${esc(f.unit)})</option>`).join('')}`,picker=()=>`<select data-lfp-select="project" aria-label="当前实验">${state.projects.filter(p=>p.status!=='archived').map(item=>`<option value="${item.id}" ${p()?.id===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select>`,button=(action,label,primary=false,attrs='')=>`<button ${primary?'class="primary"':''} data-lfp-action="${action}" ${attrs}>${label}</button>`,empty=text=>`<div class="lfp-empty"><span>⚗</span><h3>${text}</h3><p>从模板或实验指导书开始，逐步构建完整实验。</p>${button('new','＋ 创建实验',true)}</div>`,modal=(title,content,id,submit='保存')=>ctx.modal(`<div class="lfp-modal"><span class="lfp-kicker">LABFORM / EXPERIMENT STUDIO</span><h2>${title}</h2><form id="${id}">${content}<p class="lfp-error" role="alert"></p><button class="primary">${submit}</button></form></div>`);
async function boot(){try{const r=await api('/bootstrap',{legacy:ctx.store()});sync(r);ready=true;paint();}catch(e){ready=true;error=e.message;paint();}}
async function run(label,fn){busy=label;try{return await fn();}catch(e){ctx.toast(e.message);throw e;}finally{busy='';}}
async function save(project,message='实验已保存'){lastSaveError=false;const payload=clone(project);delete payload.versions;delete payload.reports;delete payload.result;delete payload.audit;try{sync(await api('/project',{project:payload}));computed=null;ctx.persist();ctx.toast(message);}catch(error){lastSaveError=true;if(error.status===409)saveConflict(ctx,payload,'LabForm');throw error;}}
function header(){return`<header class="lfp-header"><div><span class="lfp-kicker">OMNIFORM OS / RESEARCH INTELLIGENCE</span><h1>LabForm 3.0 <small>让每一次探索，有据可循。</small></h1></div><div class="lfp-actions"><span class="lfp-save">${busy?esc(busy)+'…':lastSaveError?'保存未完成，请重试':'● 工作区已同步'}</span>${button('guide','↥ 实验指导书')}${button('new','＋ 新建实验',true)}</div></header><nav class="lfp-nav">${Object.entries(nav).map(([key,title])=>`<button class="${area===key?'active':''}" data-lfp-tab="${key}">${title}</button>`).join('')}</nav>`;}
function render(){if(!ready)return'<div class="lfp-empty">正在连接科研实验工作区…</div>';if(error)return`<div class="lfp-empty"><h2>实验服务暂时不可用</h2><p>${esc(error)}</p>${button('retry','重新连接')}</div>`;return`<section class="lfp-root">${header()}<main>${({home,create:creator,notebook:studio.notebook,capture:studio.capture,data:dataPage,compute:computePage,plot:plotPage,analysis:analysisPage,report:reportPage,templates:templatesPage})[area]()}</main><input id="lfp-guide-file" hidden type="file" accept=".pdf,.docx,.txt"><input id="lfp-data-file" hidden type="file" accept=".csv,.tsv,.xlsx,.json"></section>`;}
function section(title,sub,actions=''){return`<div class="lfp-section-head"><div><span class="lfp-kicker">${sub}</span><h2>${title}</h2></div><div class="lfp-actions">${actions}</div></div>`;}
function cards(list){return`<div class="lfp-projects">${list.map(item=>{const progress=[item.rows.length>0,item.result!=null,item.reports?.length>0].filter(Boolean).length;return`<article class="lfp-project"><div class="lfp-card-head"><i>⚗</i><span class="lfp-badge">${item.status==='completed'?'已完成':item.status==='archived'?'已归档':'进行中'}</span></div><small>${esc(item.subject)}</small><h3>${esc(item.name)}</h3><p>${esc(item.purpose||'记录、计算与研究发现')}</p><div class="lfp-project-meta"><span>${item.rows.length} 组数据</span><span>${item.fields.length} 个变量</span><span>${item.reports?.length||0} 份报告</span></div><div class="lfp-progress"><i style="width:${progress/3*100}%"></i></div><footer><small>${new Date(item.updatedAt).toLocaleDateString('zh-CN')}</small><button data-lfp-open="${item.id}">继续实验 →</button></footer></article>`;}).join('')||empty('创建你的第一个实验')}</div>`;}
function home(){const projects=state.projects.filter(p=>p.status!=='archived'),rows=projects.reduce((n,p)=>n+p.rows.length,0);return`<div class="lfp-page lfp-research-home"><header class="lfp-research-masthead"><div><span>LABFORM / RESEARCH HUB</span><h2>从实验设想，到可复核的发现。</h2><p>项目、实验记录、测量数据和科学计算，沿着同一份证据展开。</p></div><span class="lfp-badge">SCIENTIFIC WORKSPACE · 3.0</span></header><div class="l3-create-grid">${[['go-create','✦','AI 创建实验','规划变量、公式和步骤'],['guide','↥','上传实验指导书','PDF / DOCX 提取后确认结构'],['go-templates','◇','从模板创建','物理、电路与传感器课程'],['hub-import','▤','导入实验数据','先选实验，再映射测量列']].map(([a,icon,title,desc])=>`<button data-lfp-action="${a}"><i>${icon}</i><strong>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="lfp-instrument-strip">${[[projects.length,'实验项目'],[rows,'原始测量'],[projects.filter(p=>p.status==='active').length,'进行中'],[projects.filter(p=>p.reports?.length).length,'已形成报告']].map(([v,l])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}<span class="lfp-integrity">● 原值保护 / 可复算 / 版本追踪</span></div><section>${section('最近实验','RECENT NOTEBOOKS',`<input id="lfp-search" aria-label="查找实验" placeholder="查找实验…" value="${esc(search)}">${button('go-templates','全部项目与模板 →')}`)}${cards(projects.filter(p=>(p.name+' '+p.subject).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,6))}</section><div class="lfp-home-bottom"><section class="lfp-panel">${section('选择一项实验，开始记录。','COURSE TEMPLATES')}<div class="lfp-template-mini">${templates.filter(t=>['hall','rc','diode','sensor'].includes(t.id)).map(t=>`<button data-lfp-template="${t.id}"><i>◇</i><div><b>${esc(t.name)}</b><small>${esc(t.description)}</small></div><span>↗</span></button>`).join('')}</div></section><section class="lfp-panel">${section('实验动态','RESEARCH ACTIVITY')}${state.audit.slice(0,6).map(a=>`<div class="lfp-activity"><i></i><div><b>${esc(a.message)}</b><small>${new Date(a.at).toLocaleString('zh-CN')}</small></div></div>`).join('')||'<p class="lfp-muted">创建、计算和报告记录将显示在这里。</p>'}</section></div></div>`;}
function creator(){return`<div class="lfp-page">${section('从一个实验想法，生成可审核的方案。','EXPERIMENT DESIGN COPILOT')}<div class="lfp-create-layout"><section class="lfp-panel lfp-compose"><div class="lfp-compose-badge">✦ AI EXPERIMENT ARCHITECT</div><h3>描述你想开展的实验</h3><form id="lfp-ai-create"><textarea name="prompt" required rows="7" placeholder="例如：创建 RC 电路放电实验，记录时间和电压，采用指数拟合，计算时间常数，并生成实验报告。"></textarea><div class="lfp-compose-tools">${button('guide','↥ 上传 PDF / Word')}<button class="primary">生成候选方案 →</button></div></form>${guide?`<div class="lfp-guide"><b>▤ ${esc(guide.name)}</b><small>${guide.text.length} 字已提取，原文保留为来源依据</small><details><summary>查看提取原文</summary><pre>${esc(guide.text)}</pre></details></div>`:''}<p class="lfp-muted">AI 生成候选结构；公式、变量单位和实验条件需要人工确认。未配置模型时可直接使用模板或手动创建。</p><div class="lfp-prompt-examples">${['霍尔效应与重复测量','RC 电路与时间常数','温度传感器标定'].map(text=>`<button type="button" data-lfp-prompt="${text}">${text} ↗</button>`).join('')}</div></section><section class="lfp-panel">${candidate?`<span class="lfp-kicker">REVIEW REQUIRED</span><h3>候选实验结构</h3><p>${esc(candidate.summary)}</p><form id="lfp-accept"><label>实验名称<input name="name" required value="${esc(candidate.project.name)}"></label><label>字段、单位、公式与绘图配置（可修改）<textarea name="schema" rows="15" spellcheck="false">${esc(JSON.stringify(candidate.project,null,2))}</textarea></label><label class="lfp-check"><input name="confirmed" required type="checkbox">我已核对字段、单位、公式和实验步骤</label><button class="primary">确认并创建实验</button></form>`:`<div class="lfp-design-empty"><div class="lfp-orbit">⚗</div><h3>你的下一次发现，从这里开始。</h3><p>系统将规划测量变量、数据表、计算公式、科学绘图与报告结构。</p><div>${['01 需求与来源','02 变量与单位','03 公式与绘图','04 审核与创建'].map(x=>`<span>${x}</span>`).join('')}</div></div>`}</section></div></div>`;}
function dataPage(){if(!p())return empty('创建实验项目');const project=p(),r=safe();return`<div class="lfp-page">${section('记录每一个原始测量值。','EXPERIMENT DATA NOTEBOOK',`${picker()}${button('settings','实验设置')}${button('field','＋ 测量字段')}${button('row','＋ 测量记录',true)}`)}<div class="lfp-stage">${['实验准备','数据采集','科学计算','曲线分析','实验报告'].map((x,i)=>`<button data-lfp-tab="${['create','data','compute','plot','report'][i]}"><i>${i+1}</i>${x}</button>`).join('')}</div><div class="lfp-notice">原始录入值与当前测量值分别保存。显示精度不会修改原始数据；计算结果不覆盖测量列。</div><div class="lfp-toolbar">${button('import','↥ 导入 CSV / Excel / JSON')}${button('bulk','▤ 批量录入')}${button('batch-edit','批量编辑')}${button('version','◇ 保存数据版本')}${button('export-csv','⇩ CSV')}${button('export-xlsx','⇩ Excel')}${button('export-json','⇩ JSON')}${button('calculate','重新计算 →',true)}</div><section class="lfp-panel lfp-table-panel"><header><div><h3>${esc(project.name)}</h3><span>${project.rows.length} 组 · ${project.fields.length} 个变量</span></div><span>自动保存 · 原始精度保护</span></header><div class="lfp-table-scroll"><table><thead><tr><th>#</th><th>实验分组</th>${project.fields.map(f=>`<th><button data-lfp-field="${f.id}">${esc(f.label)}<small>${esc(f.id)} · ${esc(f.unit||'无量纲')}${f.type==='calculated'?' · 计算列':''}</small></button></th>`).join('')}<th>来源 / 原始值</th><th></th></tr></thead><tbody>${project.rows.map((row,i)=>`<tr><td>${i+1}</td><td><input data-lfp-group="${row.id}" value="${esc(row.group||'')}" placeholder="默认组"></td>${project.fields.map(f=>`<td>${f.type==='calculated'?`<span class="lfp-calculated" data-calculated="${f.id}" data-row="${row.id}">${r?.error?'待计算':fmt(r?.rows.find(x=>x.id===row.id)?.values[f.id])}</span>`:`<input aria-label="${esc(f.label)} ${i+1}" data-lfp-cell="${f.id}" data-row="${row.id}" type="${f.type==='number'?'number':'text'}" step="any" value="${esc(row.values[f.id])}">`}</td>`).join('')}<td><details><summary>${esc(row.source||'手动录入')}</summary><pre>${esc(JSON.stringify(row.original||row.values,null,2))}</pre><small>${esc(row.at)}</small></details></td><td><button data-lfp-remove-row="${row.id}">×</button></td></tr>`).join('')||`<tr><td colspan="${project.fields.length+4}" class="lfp-empty-cell">还没有测量数据。添加记录或从文件导入，开始你的实验。</td></tr>`}</tbody></table></div></section>${r?.error?`<div class="lfp-error">${esc(r.error)}</div>`:''}<div class="lfp-home-bottom"><section class="lfp-panel"><h3>数据版本与溯源</h3>${project.versions.map(v=>`<div class="lfp-version"><span><b>${esc(v.name)}</b><small>${new Date(v.at).toLocaleString('zh-CN')}</small></span><button data-lfp-restore="${v.id}">恢复版本</button></div>`).join('')||'<p class="lfp-muted">保存版本后可恢复数据与实验配置。</p>'}<details class="lfp-evidence"><summary>已移除测量的原始记录（${project.rawArchive?.length||0}）</summary>${(project.rawArchive||[]).map(row=>`<div class="lfp-version"><small>${esc(row.id.slice(-8))} · ${esc(row.source||'手动录入')}</small><button data-lfp-recover-row="${row.id}" ${project.rows.some(r=>r.id===row.id)?'disabled':''}>恢复原始值</button></div>`).join('')}</details></section><section class="lfp-panel"><h3>质量检查</h3>${r?.findings?.length?r.findings.map(f=>`<p class="lfp-warning">${esc(f.fieldId)} = ${fmt(f.value)} · ${esc(f.reason)}</p>`).join(''):'<p class="lfp-muted">暂无 IQR 异常提示；不足四组测量时不做分位异常判断。</p>'}<p class="lfp-muted">必填、数值类型及公式依赖在计算前校验。异常值仅提示，不自动删除。</p></section></div></div>`;}
function computePage(){if(!p())return empty('先创建一个实验');const r=safe();return`<div class="lfp-page">${section('每一个结果，都能追溯到计算过程。','DETERMINISTIC SCIENTIFIC ENGINE',`${picker()}${button('calculate','运行计算',true)}`)}<div class="lfp-compute-layout"><section class="lfp-panel"><h3>统计与测量不确定度</h3>${r?.error?`<p class="lfp-error">${esc(r.error)}</p>`:r?`<div class="lfp-table-scroll"><table><thead><tr><th>变量</th><th>样本数</th><th>均值</th><th>样本标准差</th><th>A 类标准不确定度</th></tr></thead><tbody>${Object.entries(r.stats).map(([id,s])=>`<tr><td>${esc(p().fields.find(f=>f.id===id)?.label)}<small>${esc(p().fields.find(f=>f.id===id)?.unit)}</small></td><td>${s.n}</td><td>${fmt(s.mean)}</td><td>${fmt(s.std)}</td><td>${fmt(s.sem)}</td></tr>`).join('')}</tbody></table></div><details class="lfp-evidence"><summary>查看公式和使用的数据</summary><p>均值 x̄ = Σxᵢ / n；样本标准差 s = √[Σ(xᵢ−x̄)²/(n−1)]；A 类标准不确定度 uA = s/√n。单次测量的重复性无法从样本估计。</p><pre>${esc(JSON.stringify(r.stats,null,2))}</pre></details>${r.hall?`<article class="lfp-result-card"><span>霍尔系数 R_H</span><strong>${fmt(r.hall.value)} <small>m³/C</small></strong><p>斜率贡献：± ${fmt(r.hall.uncertainty)}；合成：± ${fmt(r.hall.combinedUncertainty)}（未提供的参数不确定度项未计入）</p><details><summary>公式、单位换算和中间结果</summary><pre>${esc(JSON.stringify(r.hall,null,2))}</pre></details></article>`:''}`:'<p class="lfp-muted">输入实验数据后显示真实统计结果。</p>'}${(r?.derived||[]).map(item=>`<article class="lfp-result-card"><span>${esc(item.name)}</span><strong>${fmt(item.value)} <small>${esc(item.unit)}</small></strong><p>${esc(item.formula)}</p></article>`).join('')}<h3>计算列与公式审核</h3>${p().fields.filter(f=>f.type==='calculated').map(f=>`<div class="lfp-formula-row"><code>${esc(f.id)} = ${esc(f.formula)}</code><button data-lfp-field="${f.id}">${f.confirmed?'已审核 · 编辑':'待审核'}</button></div>`).join('')||'<p class="lfp-muted">添加计算列后，可绑定测量变量执行公式。</p>'}${button('field','＋ 添加公式列')}</section><aside class="lfp-panel"><h3>不确定度传播计算器</h3><form id="lfp-propagate"><label>表达式<input name="expression" value="U/I" required></label><label>变量、值、标准不确定度（JSON）<textarea name="variables" rows="5">${esc('{"U":{"value":5,"uncertainty":0.01},"I":{"value":0.02,"uncertainty":0.0001}}')}</textarea></label><button class="primary">计算偏导与合成不确定度</button></form><hr><h3>单位换算</h3><form id="lfp-convert"><label>数值<input name="value" type="number" step="any" value="1" required></label><div class="lfp-pair"><label>从<input name="from" value="mV" required></label><label>到<input name="to" value="V" required></label></div><button>执行换算</button></form>${extraResult?`<div class="lfp-evidence"><pre>${esc(JSON.stringify(extraResult,null,2))}</pre></div>`:''}<hr><h3>显示格式</h3><label>有效数字<select data-lfp-select="precision">${[3,4,5,6,8,10,12].map(n=>`<option ${p().precision===n?'selected':''}>${n}</option>`).join('')}</select></label><label>计数方式<select data-lfp-select="notation"><option value="normal" ${p().notation==='normal'?'selected':''}>有效数字</option><option value="scientific" ${p().notation==='scientific'?'selected':''}>科学计数法</option></select></label></aside></div>${studio.uncertainty()}</div>`;}
function plotPage(){if(!p())return empty('先创建实验');const project=p(),r=safe(),fit=r?.fit;return`<div class="lfp-page">${section('从测量点，到可以解释的曲线。','SCIENTIFIC PLOT STUDIO',`${picker()}${button('fullscreen','全屏')}${button('png','⇩ PNG')}${button('svg','⇩ SVG')}`)}<div class="lfp-plot-layout"><section class="lfp-panel lfp-plot-card" id="lfp-plot-card"><header><div><h3>${esc(project.name)}</h3><p>原始数据 · 模型拟合 · 误差与残差 · 点击测量点定位原始行</p></div><span class="lfp-badge">${r?.points?.length||0} 个数据点</span></header><div class="lfp-scientific-chart" id="lfp-main-chart"></div><div class="lfp-fit-strip"><span>R² <b>${fit?.r2==null?'不可估计':fmt(fit.r2)}</b></span><span>RMSE <b>${fmt(fit?.rmse)}</b></span><span>自由度 <b>${fit?.dof??'—'}</b></span></div>${r?.fitError?`<p class="lfp-warning">${esc(r.fitError)}</p>`:''}<div class="lfp-residual-title">拟合残差 · y − ŷ</div><div id="lfp-residual-chart" class="lfp-residual-chart"></div><details class="lfp-evidence"><summary>拟合方程、参数不确定度与计算依据</summary><p>${esc(fit?.equation||'尚未拟合')}</p><p>${esc(fit?.note||'中心化并缩放 X，使用 QR 分解进行最小二乘；加权模式使用 1/σ² 权重。参数不确定度采用残差方差与设计矩阵；置信带为 1.96 倍标准误的正态近似，不是预测区间。自由度为零时不报告不确定度。')}</p><pre>${esc(JSON.stringify(fit||{},null,2))}</pre></details></section><aside class="lfp-panel lfp-plot-config"><span class="lfp-kicker">PLOT PROPERTIES</span><h3>曲线与数据绑定</h3><form id="lfp-plot-form"><label>实验条件分组<select name="group"><option value="">全部分组</option>${[...new Set(project.rows.map(r=>r.group||'默认组'))].map(group=>`<option value="${esc(group)}" ${project.plot.group===group?'selected':''}>${esc(group)}</option>`).join('')}</select></label><label>X 轴变量<select name="x">${fieldOptions(project.plot.x)}</select></label><label>Y 轴变量（可多选）<select name="ys" multiple size="4">${project.fields.map(f=>`<option value="${f.id}" ${project.plot.ys.includes(f.id)?'selected':''}>${esc(f.label)} (${esc(f.unit)})</option>`).join('')}</select></label><div class="lfp-pair"><label>基础图形<select name="type">${[['scatter','散点图'],['line','折线图'],['bar','柱状图']].map(([v,l])=>`<option value="${v}" ${project.plot.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>线型<select name="lineType">${['solid','dashed','dotted'].map(v=>`<option ${project.plot.lineType===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>拟合模型<select name="model">${[['none','不拟合'],['linear','线性最小二乘'],['poly','多项式拟合'],['exponential','指数拟合（对数域）'],['rc','RC 充放电（带偏置指数）']].map(([v,l])=>`<option value="${v}" ${project.plot.model===v?'selected':''}>${l}</option>`).join('')}</select></label><label>多项式阶数<input name="degree" type="number" min="2" max="4" value="${project.plot.degree}"></label><label>Y 误差棒字段<select name="errorField">${fieldOptions(project.plot.errorField,true)}</select></label><div class="lfp-pair"><label>X 下限<input name="xMin" type="number" step="any" value="${esc(project.plot.xMin)}"></label><label>X 上限<input name="xMax" type="number" step="any" value="${esc(project.plot.xMax)}"></label><label>Y 下限<input name="yMin" type="number" step="any" value="${esc(project.plot.yMin)}"></label><label>Y 上限<input name="yMax" type="number" step="any" value="${esc(project.plot.yMax)}"></label></div><label class="lfp-check"><input name="weighted" type="checkbox" ${project.plot.weighted?'checked':''}>按误差棒 σ 加权拟合</label><label class="lfp-check"><input name="confidence" type="checkbox" ${project.plot.confidence!==false?'checked':''}>近似 95% 均值置信带</label><label>主曲线颜色<input name="color" type="color" value="${project.plot.color}"></label><label class="lfp-check"><input name="grid" type="checkbox" ${project.plot.grid?'checked':''}>显示网格</label><label class="lfp-check"><input name="legend" type="checkbox" ${project.plot.legend?'checked':''}>显示图例</label><button class="primary">应用配置并重新拟合</button></form></aside></div></div>`;}
function analysisPage(){if(!p())return empty('先创建实验');const r=safe(),a=p().analysis;return`<div class="lfp-page">${section('把测量事实、计算结果与研究推测分开。','EVIDENCE-BASED RESEARCH ASSISTANT',picker())}<div class="lfp-create-layout"><section class="lfp-panel"><h3>实验分析助手</h3><p class="lfp-muted">AI 只接收当前实验和可验证计算依据。未配置模型时不会生成伪造分析。</p><form id="lfp-ai-analysis"><label>分析目标<textarea name="prompt" rows="6" required placeholder="解释拟合结果，分析可能误差来源，并提出下一轮实验改进建议。"></textarea></label><button class="primary">✦ 基于当前数据生成分析</button></form><h3>确定性数据诊断</h3><div class="lfp-result-card"><span>有效数据点</span><strong>${r?.points?.length||0}</strong><p>${r?.findings?.length||0} 条 IQR 异常提醒</p></div>${r?.fit?`<p>R² = ${fmt(r.fit.r2)}；RMSE = ${fmt(r.fit.rmse)}。</p><p class="lfp-muted">相关程度不代表因果；单个拟合指标不能证明实验结论。</p>`:''}</section><section class="lfp-panel">${a?`${[['observations','原始测量事实'],['calculations','确定性计算结果'],['hypotheses','AI 推断 · 待验证'],['suggestions','实验改进建议']].map(([key,title])=>`<article class="lfp-analysis-section"><span class="lfp-kicker">${title}</span>${(a[key]||[]).map(text=>`<p>${esc(text)}</p>`).join('')}</article>`).join('')}<details><summary>计算来源与模型</summary><pre>${esc(JSON.stringify({model:a.model,at:a.at,basis:a.basis},null,2))}</pre></details>${button('analysis-to-report','采用结论草稿，进入报告 →',true)}`:`<div class="lfp-design-empty"><div class="lfp-orbit">✦</div><h3>实验数据，会说话。</h3><p>分析结果会展示数据证据与推断边界，最终结论由研究者确认。</p></div>`}</section></div>${studio.evidence()}</div>`;}
function reportHTML(){const project=p(),r=safe(),report=project.report||{};return`<article class="lfp-paper"><div class="lfp-paper-top">LABFORM / RESEARCH REPORT</div><h1>${esc(project.name)}${report.format==='research'?'科研记录摘要':project.name.endsWith('实验')?'报告':'实验报告'}</h1><div class="lfp-paper-meta">实验人员：${esc(project.researcher||'未填写')}　日期：${esc(project.date)}　项目 ID：${esc(project.id)}</div><h2>一、实验目的与原理</h2><p>${esc(project.purpose)}</p><p>${esc(project.principle)}</p><h2>二、仪器、参数与步骤</h2><p>${esc(project.instruments)}</p><p>${report.format==='research'?'（实验步骤详见原始记录）':esc(project.protocol)}</p><pre>${esc(JSON.stringify(project.parameters,null,2))}</pre><h2>三、原始记录与数据处理</h2>${r?.error?`<p class="lfp-error">计算未完成：${esc(r.error)}</p>`:''}${!project.rows.length?'<p>待填写原始测量数据；未生成数值结果。</p>':''}<table><thead><tr><th>分组</th>${project.fields.map(f=>`<th>${esc(f.label)} (${esc(f.unit)})</th>`).join('')}</tr></thead><tbody>${(r?.rows||[]).map(row=>`<tr><td>${esc(row.group)}</td>${project.fields.map(f=>`<td>${typeof row.values[f.id]==='number'?fmt(row.values[f.id]):esc(row.values[f.id])}</td>`).join('')}</tr>`).join('')}</tbody></table><h2>四、曲线与拟合分析</h2><div id="lfp-report-chart" style="height:340px"></div><p>${esc(r?.fit?.equation||r?.fitError||'未执行拟合')}</p><p>R²：${fmt(r?.fit?.r2)}　RMSE：${fmt(r?.fit?.rmse)}</p>${r?.hall?`<p>${esc(r.hall.formula)}；R_H = ${fmt(r.hall.value)} ${r.hall.unit}</p>`:''}${(r?.derived||[]).map(item=>`<p>${esc(item.name)}：${fmt(item.value)} ${esc(item.unit)}；${esc(item.formula)}</p>`).join('')}${r?.uncertainty?`<p>uA=${fmt(r.uncertainty.uA)}；uB=${fmt(r.uncertainty.uB)}；uc=${fmt(r.uncertainty.combined)}；U=${fmt(r.uncertainty.expanded)} ${esc(r.uncertainty.unit)}（k=${r.uncertainty.k}）。${esc(r.uncertainty.assumptions)}</p>`:''}<h2>五、误差与不确定度讨论</h2><p>${rich(report.discussion||'请结合仪器精度、测量条件与计算结果填写。')}</p><h2>六、实验结论</h2><p>${rich(report.conclusion||'请基于测量事实和计算结果填写结论。')}</p><h2>备注</h2><p>${esc(report.notes||'')}</p><footer>测量事实与计算结果由实验数据产生；AI 草稿需人工核对。数据行数 ${project.rows.length} · 项目 ${esc(project.id)}</footer></article>`;}
function reportPage(){if(!p())return empty('先创建实验');return`<div class="lfp-page">${section('从实验记录，到可复核的研究报告。','REPORT WRITING STUDIO',`${picker()}${button('report-draft','生成数据报告草稿')}${button('report-save','保存报告版本',true)}${button('export-docx','⇩ Word')}${button('pdf','打印 / PDF')}`)}<div class="lfp-report-layout"><aside class="lfp-panel"><h3>报告内容</h3><div class="lfp-rich-toolbar"><button data-lfp-format="bold"><b>B</b></button><button data-lfp-format="italic"><i>I</i></button><button data-lfp-format="list">≡ 列表</button></div><form id="lfp-report-form"><label>模板<select name="format"><option value="standard">标准实验报告</option><option value="research" ${p().report.format==='research'?'selected':''}>科研记录摘要</option></select></label><label>误差讨论<textarea name="discussion" rows="6">${esc(p().report.discussion)}</textarea></label><label>结论<textarea name="conclusion" rows="6">${esc(p().report.conclusion)}</textarea></label><label>备注<textarea name="notes" rows="3">${esc(p().report.notes)}</textarea></label><button class="primary">更新实时预览</button></form><p class="lfp-muted">文本使用安全编辑，换行保留。表格、公式和曲线根据实验自动插入。</p><h3>报告版本</h3>${p().reports.map((v,i)=>`<div class="lfp-version"><span><b>版本 ${p().reports.length-i}</b><small>${new Date(v.at).toLocaleString('zh-CN')}</small></span><button data-lfp-report-restore="${v.id}">采用内容</button></div>`).join('')||'<p class="lfp-muted">保存后生成不可变数据与报告快照。</p>'}</aside><div class="lfp-report-preview" id="lfp-report-preview">${reportHTML()}</div></div></div>`;}
function templatesPage(){return`<div class="lfp-page">${section('专业实验结构，随你的研究自由扩展。','TEMPLATE LIBRARY & PROJECT MANAGEMENT',button('new','＋ 空白实验',true))}<div class="lfp-template-grid">${templates.map((t,i)=>`<article class="lfp-panel"><div class="lfp-template-art art-${i}"><span>${['⌁','∿','↗','≋','◈','⚗'][i%6]}</span><svg viewBox="0 0 180 60"><path d="M5 50 Q45 45 65 25 T110 20 T175 5" fill="none" stroke="currentColor" stroke-width="2"/></svg></div><small>${t.subject}</small><h3>${t.name}</h3><p>${t.description}</p><span class="lfp-muted">${t.fields.length} 个测量变量 · ${t.model==='none'?'多曲线测量':'确定性拟合'}</span><button class="primary" data-lfp-template="${t.id}">使用模板 →</button></article>`).join('')}${state.templates.map(t=>`<article class="lfp-panel"><small>我的自定义模板</small><h3>${esc(t.name)}</h3><p>${t.fields.length} 个变量 · ${esc(t.subject)}</p><button data-lfp-custom-template="${t.id}">使用模板 →</button></article>`).join('')}</div>${section('实验项目管理','ALL EXPERIMENTS',button('archived',showArchived?'查看进行中':'查看归档'))}${cards(state.projects.filter(p=>showArchived?p.status==='archived':p.status!=='archived'))}${p()?`<section class="lfp-panel">${section(esc(p().name),'CURRENT PROJECT',`${picker()}${button('settings','编辑信息')}${button('duplicate','复制项目')}${button('complete',p().status==='completed'?'重新开展':'标记完成')}${button('archive',p().status==='archived'?'恢复归档':'归档项目')}${button('save-template','保存为模板')}`)}<h3>连接 OmniForm OS 的其他引擎</h3><div class="lfp-integrations">${[['docmorph','DocMorph','读取实验指导书'],['exam','ExamCraft','带实验来源创建预习测验'],['flowform','FlowForm','提交实验报告审核'],['adaptform','AdaptForm','生成测量采集表'],['tablemind','TableMind','分析实验与计算数据'],['pilot','FormPilot','创建实验教学业务应用'],['appcanvas','AppCanvas','嵌入实验数据门户']].map(([id,name,description])=>`<button data-lfp-integrate="${id}"><strong>${name} ↗</strong><small>${description}</small></button>`).join('')}</div></section>`:''}</div>`;}
function chartOption(residual=false){const project=p(),r=safe(),fields=project.fields,axis=id=>{const f=fields.find(f=>f.id===id);return(f?.label||id)+(f?.unit?' ('+f.unit+')':'');};const rows=(r?.rows||[]).filter(row=>!project.plot.group||(row.group||'默认组')===project.plot.group),series=[];if(residual){series.push({type:'scatter',name:'拟合残差',data:(r?.fit?.residuals||[]).map(p=>[p.x,p.residual]),symbolSize:7,itemStyle:{color:'#a78bcf'},markLine:{silent:true,data:[{yAxis:0}],symbol:'none',lineStyle:{color:'#b8aac8',type:'dashed'}}});}else{const groups=[...new Set(rows.map(row=>row.group||'默认组'))];for(const [index,id]of project.plot.ys.entries())for(const group of groups){series.push({name:axis(id)+(groups.length>1?' · '+group:''),type:project.plot.type||'scatter',symbolSize:7,showSymbol:true,lineStyle:{type:project.plot.lineType||'solid'},itemStyle:{color:index===0?project.plot.color:undefined},data:rows.filter(row=>(row.group||'默认组')===group&&row.values[id]!==''&&row.values[id]!=null).map(row=>[Number(row.values[project.plot.x]),Number(row.values[id])]).sort((a,b)=>a[0]-b[0])});}if(r?.fit&&r.points.length){const min=Math.min(...r.points.map(p=>p.x)),max=Math.max(...r.points.map(p=>p.x));series.push({type:'line',name:'拟合曲线',showSymbol:false,lineStyle:{color:'#c2846b',width:2},data:Array.from({length:100},(_,i)=>{const x=min+(max-min)*i/99;return[x,predicted(r.fit,x)];})});}if(r?.fit?.covariance&&r.fit.dof>0&&project.plot.confidence!==false&&r.fit.model!=='exponential'){const fit=r.fit,min=Math.min(...r.points.map(p=>p.x)),max=Math.max(...r.points.map(p=>p.x)),band=Array.from({length:70},(_,i)=>{const x=min+(max-min)*i/69,z=(x-fit.center)/fit.scale,basis=fit.coefficients.map((_,j)=>z**j),variance=basis.reduce((sum,a,j)=>sum+a*basis.reduce((n,b,k)=>n+b*fit.covariance[j][k],0),0),y=predicted(fit,x),margin=1.96*Math.sqrt(Math.max(0,variance));return[x,y-margin,y+margin];});series.unshift({type:'custom',name:'近似95%均值置信带',silent:true,renderItem:(params,api)=>({type:'polygon',shape:{points:[...band.map(p=>api.coord([p[0],p[1]])),...band.slice().reverse().map(p=>api.coord([p[0],p[2]]))]},style:{fill:'rgba(154,124,209,.12)',stroke:'none'}}),data:[0],z:0});}if(project.plot.errorField)series.push({type:'custom',name:'Y 误差棒',renderItem:(params,api)=>{const x=api.value(0),y=api.value(1),e=api.value(2),low=api.coord([x,y-e]),high=api.coord([x,y+e]);return{type:'group',children:[{type:'line',shape:{x1:low[0],y1:low[1],x2:high[0],y2:high[1]},style:{stroke:project.plot.color}},{type:'line',shape:{x1:low[0]-4,y1:low[1],x2:low[0]+4,y2:low[1]},style:{stroke:project.plot.color}},{type:'line',shape:{x1:high[0]-4,y1:high[1],x2:high[0]+4,y2:high[1]},style:{stroke:project.plot.color}}]};},data:r?.points.map(p=>[p.x,p.y,p.error])||[]});}return{animationDuration:180,color:[project.plot.color,'#6ca6bb','#c18b69','#86ad89'],tooltip:{trigger:'item',renderMode:'richText'},legend:{show:!residual&&project.plot.legend,top:0,textStyle:{fontSize:10}},grid:{left:70,right:30,top:45,bottom:60},xAxis:{type:'value',name:axis(project.plot.x),nameLocation:'middle',nameGap:35,...(project.plot.xMin!==''?{min:Number(project.plot.xMin)}:{}),...(project.plot.xMax!==''?{max:Number(project.plot.xMax)}:{}),splitLine:{show:project.plot.grid,lineStyle:{color:'#eeeaf3'}}},yAxis:{type:'value',name:residual?'残差':axis(project.plot.ys[0]),nameTextStyle:{fontSize:10},scale:true,...(!residual&&project.plot.yMin!==''?{min:Number(project.plot.yMin)}:{}),...(!residual&&project.plot.yMax!==''?{max:Number(project.plot.yMax)}:{}),splitLine:{show:project.plot.grid,lineStyle:{color:'#eeeaf3'}}},dataZoom:residual?[]:[{type:'inside'},{type:'slider',height:15,bottom:5}],series};}
function afterRender(){const main=document.querySelector('#lfp-main-chart,#lfp-report-chart');if(main&&p())plotChart=scientificChart(main,p(),safe(),{onPoint:id=>{area='data';paint();const cell=[...document.querySelectorAll('[data-lfp-cell]')].find(el=>el.dataset.row===id);cell?.scrollIntoView({block:'center'});cell?.focus({preventScroll:true});}});const residual=document.querySelector('#lfp-residual-chart');if(residual&&p())residualChart=scientificChart(residual,p(),safe(),{residual:true});}
function fieldModal(id){const f=p().fields.find(f=>f.id===id)||{id:'',label:'',type:'number',unit:'',formula:'',required:false,confirmed:false};modal(id?'编辑实验变量':'添加测量 / 计算变量',`<input name="oldId" hidden value="${esc(id||'')}"><div class="lfp-pair"><label>变量 ID<input name="id" required pattern="[A-Za-z_][A-Za-z0-9_]*" value="${esc(f.id)}"></label><label>字段标题<input name="label" required value="${esc(f.label)}"></label></div><div class="lfp-pair"><label>类型<select name="type">${[['number','测量数字'],['text','文本信息'],['calculated','计算列']].map(([v,l])=>`<option value="${v}" ${f.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>物理单位<input name="unit" value="${esc(f.unit)}" placeholder="mV / mA / mT / s"></label></div><div class="lfp-pair"><label>测量下限（可选）<input name="min" type="number" step="any" value="${esc(f.min??'')}"></label><label>测量上限（可选）<input name="max" type="number" step="any" value="${esc(f.max??'')}"></label></div><label>计算公式（仅计算列）<input name="formula" value="${esc(f.formula||'')}" placeholder="例如：(V1+V2+V3)/3"></label><label class="lfp-check"><input type="checkbox" name="required" ${f.required?'checked':''}>必填</label><label class="lfp-check"><input type="checkbox" name="confirmed" ${f.confirmed?'checked':''}>我已核对公式和输出单位</label>${id?button('remove-field','删除此字段',false,`data-id="${id}"`):''}`,'lfp-field');}
function settings(){const project=p();modal('实验信息与仪器参数',`<label>实验名称<input name="name" required value="${esc(project.name)}"></label><div class="lfp-pair"><label>学科<input name="subject" value="${esc(project.subject)}"></label><label>实验人员<input name="researcher" value="${esc(project.researcher)}"></label><label>日期<input name="date" type="date" value="${project.date}"></label></div>${['purpose','principle','instruments','protocol'].map((key,i)=>`<label>${['实验目的','实验原理','实验仪器','实验步骤'][i]}<textarea name="${key}" rows="3">${esc(project[key])}</textarea></label>`).join('')}<label>仪器参数（JSON，包含 value 和 unit）<textarea name="parameters" rows="5">${esc(JSON.stringify(project.parameters,null,2))}</textarea></label>`,'lfp-settings');}
async function exportBinary(format){const image=await plotChart?.getDataURL({type:'png',pixelRatio:2,backgroundColor:chartBackground()}),response=await fetch('/api/lab/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:p().id,format,image})});if(!response.ok)throw new Error((await response.json()).error);download(await response.blob(),p().name+'.'+format,response.headers.get('content-type'));}
function downloadImage(url,name){const index=url.indexOf(','),header=url.slice(0,index),encoded=url.slice(index+1),mime=header.slice(5).split(';')[0],content=header.includes(';base64')?Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)):decodeURIComponent(encoded);download(content,name,mime);}
function download(text,name,type='text/plain'){void(async()=>{const blob=new Blob([text],{type}),bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const result=await api('/file',{name,type,base64:btoa(binary)}),a=document.createElement('a');a.href=result.downloadUrl;a.download=name;a.textContent='下载就绪：'+name;a.className='lfp-ready-download';document.querySelector('.lfp-ready-download')?.remove();document.querySelector('.lfp-header .lfp-actions')?.append(a);a.click();})().catch(error=>ctx.toast(error.message));}
function importMeasurements(name,rawRows){const table=rowsToTable(name,rawRows);table.records.forEach((r,i)=>r.rawValues=Object.fromEntries(table.fields.map((f,j)=>[f.id,rawRows[i+1]?.[j]??''])));return table;}
function importPreview(){const table=importDraft;modal('导入预览与变量映射',`<p>${table.records.length} 条记录；确认后追加到当前实验，不覆盖已有测量。</p><div class="lfp-import-map">${table.fields.map(f=>`<label>${esc(f.name)}<select name="map_${f.id}"><option value="">忽略此列</option>${p().fields.filter(f=>f.type!=='calculated').map(target=>`<option value="${target.id}" ${f.name===target.label||f.name===target.id?'selected':''}>${esc(target.label)} (${esc(target.unit)})</option>`).join('')}</select></label>`).join('')}</div><details open><summary>前五条原始记录</summary><pre>${esc(JSON.stringify(table.records.slice(0,5),null,2))}</pre></details>`,'lfp-import-confirm','确认导入');}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-lfp-action],[data-lfp-tab],[data-lfp-open],[data-lfp-template],[data-lfp-custom-template],[data-lfp-field],[data-lfp-remove-row],[data-lfp-restore],[data-lfp-prompt],[data-lfp-report-restore],[data-lfp-integrate],[data-lfp-recover-row]');if(!el)return;const d=el.dataset;try{if(d.lfpRecoverRow){const project=clone(p()),row=project.rawArchive.find(r=>r.id===d.lfpRecoverRow);project.rows.push({...clone(row),values:clone(row.original||row.values),at:stamp()});await save(project,'已恢复原始测量');paint();return;}if(d.lfpTab){area=d.lfpTab;paint();return;}if(d.lfpOpen){activeId=d.lfpOpen;area='data';paint();return;}if(d.lfpTemplate||d.lfpCustomTemplate){let project;if(d.lfpTemplate)project=createExperiment(d.lfpTemplate);else{project=clone(state.templates.find(t=>t.id===d.lfpCustomTemplate));project.id=uid('experiment');project.createdAt=stamp();project.rows=[];project.versions=[];project.reports=[];}await save(project,'实验结构已创建，请填写真实测量数据');activeId=project.id;area='data';paint();return;}if(d.lfpPrompt){document.querySelector('#lfp-ai-create textarea').value='创建一个'+d.lfpPrompt+'实验，规划测量字段、单位、数据处理公式和绘图配置。';return;}if(d.lfpField){fieldModal(d.lfpField);return;}if(d.lfpRemoveRow){if(!confirm('删除当前测量记录？已保存的数据版本仍可恢复。'))return;const project=clone(p());project.rows=project.rows.filter(r=>r.id!==d.lfpRemoveRow);await save(project);paint();return;}if(d.lfpRestore){if(!confirm('恢复这个数据版本和实验配置？'))return;sync(await api('/version',{projectId:p().id,expectedProjectRevision:p().storageRevision||0,restoreId:d.lfpRestore}));paint();return;}if(d.lfpReportRestore){const version=p().reports.find(r=>r.id===d.lfpReportRestore);const project=clone(p());project.report=clone(version.content);await save(project);paint();return;}if(d.lfpIntegrate){await ctx.integrate?.(d.lfpIntegrate,p(),safe());ctx.toast('已关联实验项目与来源版本');return;}const a=d.lfpAction;if(a==='retry'){error='';await boot();return;}if(a==='go-create'||a==='go-templates'){area=a==='go-create'?'create':'templates';paint();return;}if(a==='guide'){document.querySelector('#lfp-guide-file').click();return;}if(a==='import'){document.querySelector('#lfp-data-file').click();return;}if(a==='new'){modal('创建实验项目',`<label>实验名称<input name="name" required placeholder="例如：传感器灵敏度研究"></label><label>实验结构<select name="templateId">${templates.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></label>`,'lfp-new','创建实验');return;}if(a==='row'){modal('添加原始测量记录',`<label>实验分组<input name="group" value="默认组"></label>${p().fields.filter(f=>f.type!=='calculated').map(f=>`<label>${esc(f.label)} (${esc(f.unit)})<input name="${f.id}" type="${f.type==='number'?'number':'text'}" step="any" ${f.required?'required':''}></label>`).join('')}`,'lfp-row');return;}if(a==='field'){fieldModal();return;}if(a==='settings'){settings();return;}if(a==='export-json'){download(JSON.stringify({projectId:p().id,projectName:p().name,fields:p().fields,records:p().rows,result:safe(),exportedAt:stamp()},null,2),p().name+'.json','application/json');return;}if(a==='batch-edit'){modal('批量编辑当前测量记录',`<p>保留记录 ID，编辑 values 和 group。原始值仍由服务端保护。</p><textarea name="rows" required rows="15">${esc(JSON.stringify(p().rows.map(r=>({id:r.id,group:r.group,values:r.values})),null,2))}</textarea>`,'lfp-batch-edit','校验并应用更改');return;}if(a==='bulk'){modal('批量录入实验数据',`<p>首行使用变量 ID 或字段标题，支持 CSV 或制表符分隔。</p><textarea name="text" required rows="9" placeholder="${esc(p().fields.filter(f=>f.type!=='calculated').map(f=>f.id).join(','))}"></textarea>`,'lfp-bulk','预览数据映射');return;}if(a==='version'){modal('保存实验数据版本','<label>版本说明<input name="name" required placeholder="例如：第一轮原始测量"></label>','lfp-version');return;}if(a==='calculate'){await run('计算中',async()=>sync(await api('/calculate',{projectId:p().id})));area='compute';paint();return;}if(['duplicate','complete','archive','save-template'].includes(a)){const response=await api('/action',{projectId:p().id,expectedProjectRevision:p().storageRevision||0,action:a==='save-template'?'template':a});sync(response);if(a==='duplicate')activeId=response.result.id;ctx.toast('实验管理操作已保存');paint();return;}if(a==='archived'){showArchived=!showArchived;paint();return;}if(a==='remove-field'){if(!confirm('删除此字段和当前测量列值？原始记录与历史版本仍保留。'))return;const project=clone(p());project.fields=project.fields.filter(f=>f.id!==d.id);project.rows.forEach(r=>delete r.values[d.id]);project.plot.ys=project.plot.ys.filter(id=>id!==d.id);await save(project);ctx.closeModal();paint();return;}if(a==='analysis-to-report'){const project=clone(p());project.report.conclusion=project.analysis?.conclusion||'';project.report.discussion=(project.analysis?.hypotheses||[]).map(x=>'[AI 推断，待验证] '+x).join('\n');await save(project);area='report';paint();return;}if(a==='report-draft'){const result=safe();if(!result||result.error)throw new Error(result?.error||'请先录入有效测量数据');const project=clone(p());project.report.conclusion=`本实验记录 ${result.rows.length} 组测量。${result.fit?`采用 ${result.fit.model} 模型，R²=${fmt(result.fit.r2)}，RMSE=${fmt(result.fit.rmse)}。`:''}${result.hall?`霍尔系数为 ${fmt(result.hall.value)} m³/C。`:''}以上为确定性计算摘要，实验机理与结论请人工补充。`;project.report.discussion=`发现 ${result.findings.length} 条 IQR 异常提醒。拟合参数标准不确定度仅反映当前模型的残差贡献，不包含全部仪器系统误差。`;await save(project);paint();return;}if(a==='report-save'){sync(await api('/report',{projectId:p().id,content:p().report}));ctx.toast('报告快照已保存');paint();return;}if(a==='export-docx'||a==='export-xlsx'){await run('准备导出',()=>exportBinary(a==='export-docx'?'docx':'xlsx'));return;}if(a==='export-csv'){const q=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',result=safe();if(result?.error)throw new Error(result.error);download('\ufeff'+[p().fields.map(f=>q(f.label+(f.unit?' ('+f.unit+')':''))).join(','),...(result?.rows||[]).map(r=>p().fields.map(f=>q(r.values[f.id])).join(','))].join('\r\n'),p().name+'.csv','text/csv;charset=utf-8');return;}if(a==='hub-import'){if(!p()){ctx.toast('请先从模板创建实验，再导入测量数据');area='templates';paint();return;}area='data';paint();document.querySelector('#lfp-data-file').click();return;}if(a==='fullscreen'){await document.querySelector('#lfp-plot-card')?.requestFullscreen?.();return;}if(a==='png'){if(!plotChart)throw new Error('请先打开曲线工作室');const url=await plotChart.getDataURL({type:'png',pixelRatio:3,backgroundColor:chartBackground()}),link=document.createElement('a');downloadImage(url,p().name+'.png');return;}if(a==='svg'){if(!plotChart)throw Error('请先打开科学绘图');const url=await plotChart.getDataURL({type:'svg',pixelRatio:1}),link=document.createElement('a');downloadImage(url,p().name+'.svg');return;}if(a==='pdf'){window.print();return;}}catch(e){ctx.toast(e.message);}});
document.addEventListener('change',async event=>{const el=event.target,d=el.dataset;try{if(el.id==='lfp-guide-file'){const file=el.files[0];if(!file)return;await run('解析实验指导书',async()=>{const {parseFile}=await import('./vendor/docmorph/parser.js');const parsed=await parseFile(file);if(!parsed.segments.length)throw new Error('未提取到可读文本。扫描 PDF 请先通过 DocMorph OCR 识别。');guide={name:file.name,text:parsed.segments.map(s=>`${s.location}: ${s.text}`).join('\n')};area='create';paint();ctx.toast('指导书已提取，请描述需求后生成候选方案');});return;}if(el.id==='lfp-data-file'){const file=el.files[0];if(!file)return;if(file.size>15*1024*1024)throw new Error('文件不能超过 15 MB');if(file.name.toLowerCase().endsWith('.xlsx')){const {parseExcelTable}=await import('./vendor/tablemind-import.js');const result=await parseExcelTable(file);importDraft=importMeasurements(file.name,result.rows);}else if(file.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(await file.text()),rows=Array.isArray(parsed)?parsed:parsed.records;if(!Array.isArray(rows)||!rows.length)throw new Error('JSON 必须包含记录数组');const headers=Object.keys(rows[0].values||rows[0]);importDraft=importMeasurements(file.name,[headers,...rows.map(r=>headers.map(k=>(r.values||r)[k]))]);}else importDraft=importMeasurements(file.name,parseDelimited(await file.text(),file.name.endsWith('.tsv')?'\t':','));importPreview();return;}if(d.lfpSelect==='project'){activeId=el.value;extraResult=null;paint();return;}if(d.lfpSelect){const project=clone(p());project[d.lfpSelect]=d.lfpSelect==='precision'?Number(el.value):el.value;await save(project);paint();return;}if(d.lfpCell||d.lfpGroup){const project=clone(p()),row=project.rows.find(r=>r.id===(d.row||d.lfpGroup));if(d.lfpCell){const f=project.fields.find(f=>f.id===d.lfpCell);row.values[f.id]=el.value===''?'':f.type==='number'?Number(el.value):el.value;}else row.group=el.value;row.modifiedAt=stamp();await save(project,'测量记录已保存');const result=safe();document.querySelectorAll('[data-calculated]').forEach(cell=>cell.textContent=result?.error?'待计算':fmt(result?.rows?.find(r=>r.id===cell.dataset.row)?.values[cell.dataset.calculated]));return;}}catch(e){ctx.toast(e.message);}});
// Native change already fires on blur; a second focusout write races the storage revision.
let reportTimer;document.addEventListener('mousedown',event=>{if(event.target.closest('[data-lfp-format]'))event.preventDefault();});document.addEventListener('click',event=>{const button=event.target.closest('[data-lfp-format]');if(!button)return;const textarea=document.querySelector('#lfp-report-form textarea:focus')||document.querySelector('#lfp-report-form textarea');if(!textarea)return;const start=textarea.selectionStart,end=textarea.selectionEnd,selected=textarea.value.slice(start,end)||'文本',kind=button.dataset.lfpFormat,insert=kind==='bold'?'**'+selected+'**':kind==='italic'?'*'+selected+'*':'\n- '+selected;textarea.setRangeText(insert,start,end,'select');textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.focus();});
document.addEventListener('input',event=>{if(event.target.closest('#lfp-report-form')){const form=event.target.closest('form');p().report={...p().report,...Object.fromEntries(new FormData(form))};const chart=document.querySelector('#lfp-report-chart');const preview=document.querySelector('#lfp-report-preview');if(preview){plotChart?.dispose();preview.innerHTML=reportHTML();afterRender();}clearTimeout(reportTimer);const project=clone(p());reportTimer=setTimeout(()=>save(project,'报告草稿已自动保存').catch(e=>ctx.toast(e.message)),700);}if(event.target.id==='lfp-search'){search=event.target.value;const caret=event.target.selectionStart;paint();const input=document.querySelector('#lfp-search');input?.focus();input?.setSelectionRange(caret,caret);}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.getAttribute('id')?.startsWith('lfp-'))return;event.preventDefault();const data=new FormData(form),d=Object.fromEntries(data),submit=form.querySelector('button.primary');if(submit){submit.disabled=true;submit.dataset.original=submit.textContent;submit.textContent='处理中…';}try{const id=form.getAttribute('id');if(id==='lfp-new'){const project=createExperiment(d.templateId,d.name);await save(project);activeId=project.id;area='data';}if(id==='lfp-ai-create'){const r=await run('AI 规划实验',()=>api('/ai/create',{prompt:d.prompt,document:guide?.text,documentName:guide?.name}));candidate=r.candidate;paint();return;}if(id==='lfp-accept'){const project=JSON.parse(d.schema);project.name=d.name;project.formulaConfirmed=true;project.fields.forEach(f=>{if(f.type==='calculated')f.confirmed=true;});await save(project);activeId=project.id;candidate=null;area='data';}if(id==='lfp-settings'){const project={...clone(p()),name:d.name,subject:d.subject,researcher:d.researcher,date:d.date,purpose:d.purpose,principle:d.principle,instruments:d.instruments,protocol:d.protocol,parameters:JSON.parse(d.parameters)};await save(project);}if(id==='lfp-field'){const project=clone(p()),field={id:d.id,label:d.label,type:d.type,unit:d.unit,formula:d.formula,required:data.has('required'),confirmed:data.has('confirmed'),...(d.min!==''?{min:Number(d.min)}:{}),...(d.max!==''?{max:Number(d.max)}:{})},index=project.fields.findIndex(f=>f.id===d.oldId);if(d.oldId&&d.oldId!==d.id&&project.fields.some(f=>f.id!==d.oldId&&f.formula?.match(new RegExp('\\b'+d.oldId+'\\b'))))throw new Error('其他公式引用了旧变量，请先修改依赖');if(index<0)project.fields.push(field);else{project.fields[index]=field;if(d.oldId!==d.id){project.rows.forEach(r=>{r.values[d.id]=r.values[d.oldId];delete r.values[d.oldId];});if(project.plot.x===d.oldId)project.plot.x=d.id;project.plot.ys=project.plot.ys.map(id=>id===d.oldId?d.id:id);}}await save(project);}if(id==='lfp-row'){const project=clone(p()),values={};for(const f of project.fields.filter(f=>f.type!=='calculated'))values[f.id]=f.type==='number'&&d[f.id]!==''?Number(d[f.id]):d[f.id];project.rows.push({id:uid('row'),values,original:Object.fromEntries(project.fields.filter(f=>f.type!=='calculated').map(f=>[f.id,d[f.id]])),group:d.group,source:'手动录入',at:stamp()});project.stage='data';await save(project);}if(id==='lfp-version')sync(await api('/version',{projectId:p().id,name:d.name}));if(id==='lfp-propagate'){extraResult=propagate(d.expression,JSON.parse(d.variables));paint();return;}if(id==='lfp-convert'){extraResult={input:Number(d.value),from:d.from,to:d.to,result:convertUnit(d.value,d.from,d.to)};paint();return;}if(id==='lfp-plot-form'){const ys=data.getAll('ys');if(!ys.length)throw new Error('至少选择一个 Y 轴变量');for(const axis of ['x','y'])if(d[axis+'Min']!==''&&d[axis+'Max']!==''&&Number(d[axis+'Min'])>=Number(d[axis+'Max']))throw new Error('坐标下限必须小于上限');const project=clone(p());project.plot={...project.plot,...d,ys,degree:Number(d.degree),grid:data.has('grid'),legend:data.has('legend'),weighted:data.has('weighted'),confidence:data.has('confidence')};await save(project);sync(await api('/calculate',{projectId:project.id}));}if(id==='lfp-ai-analysis'){sync(await run('AI 分析实验',()=>api('/ai/analyze',{projectId:p().id,prompt:d.prompt})));paint();return;}if(id==='lfp-report-form'){const project=clone(p());project.report={...project.report,...d};await save(project);}if(id==='lfp-batch-edit'){const rows=JSON.parse(d.rows);if(!Array.isArray(rows)||rows.some(r=>!p().rows.some(x=>x.id===r.id)))throw new Error('请保留已有记录 ID；新记录请通过添加或导入创建');const project=clone(p());project.rows=rows.map(r=>({...project.rows.find(x=>x.id===r.id),...r,modifiedAt:stamp()}));evaluateExperiment({...project,plot:{...project.plot,model:'none'}});await save(project,'批量测量修改已保存');}if(id==='lfp-bulk'){importDraft=importMeasurements('批量录入',parseDelimited(d.text,d.text.includes('\t')?'\t':','));importPreview();return;}if(id==='lfp-import-confirm'){const mapping=Object.fromEntries(importDraft.fields.map(f=>[f.id,d['map_'+f.id]]).filter(([,v])=>v));if(!Object.keys(mapping).length)throw new Error('请映射至少一个变量');if(new Set(Object.values(mapping)).size!==Object.values(mapping).length)throw new Error('不同数据列不能映射到同一个变量');const required=p().fields.filter(f=>f.required&&f.type!=='calculated');if(required.some(f=>!Object.values(mapping).includes(f.id)))throw new Error('请映射所有必填测量变量');const project=clone(p());for(const [index,row]of importDraft.records.entries()){const values={};for(const [source,target]of Object.entries(mapping)){const field=project.fields.find(f=>f.id===target),raw=row[source];if(field.type==='number'&&raw!==''&&!Number.isFinite(Number(raw)))throw new Error(`第 ${index+2} 行「${field.label}」不是有效数字`);values[target]=field.type==='number'&&raw!==''?Number(raw):raw;}project.rows.push({id:uid('row'),values,original:Object.fromEntries(Object.entries(mapping).map(([source,target])=>[target,row.rawValues?.[source]??row[source]])),group:'导入数据',source:importDraft.name,at:stamp()});}await save(project,'实验数据已导入');importDraft=null;}ctx.closeModal();paint();}catch(e){const error=form.querySelector('.lfp-error');if(error)error.textContent=e.message;ctx.toast(e.message);}finally{if(submit){submit.disabled=false;submit.textContent=submit.dataset.original;}}});
window.addEventListener('resize',()=>{plotChart?.resize();residualChart?.resize();});
const studio=createLabStudio3({project:p,result:safe,state:()=>state,esc,button,picker,section,save,api,sync,paint,toast:ctx.toast,download});
boot();return{render,afterRender,snapshot:()=>state,exportData:()=>{const project=p(),result=safe();return{project,result};}};
}
